SELECT s.s_store_name, s.s_state, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(sr.sr_return_amt) AS total_returns FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN store_returns sr ON sr.sr_ticket_number = ss.ss_ticket_number WHERE s.s_country = 'United States' AND ss.ss_sold_date_sk >= 2452150 AND ss.ss_sold_date_sk <= 2451874 GROUP BY s.s_store_name, s.s_state
